<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Contrato #<?= (int)$record['id'] ?></title><link rel="stylesheet" href="<?= e(url('assets/css/modulo5-print.css')) ?>"><script src="<?= e(url('assets/js/app.js')) ?>" defer></script></head><body>
<button data-print-page>Imprimir</button><h1>Contrato #<?= (int)$record['id'] ?> — <?= e($record['titulo']) ?></h1><p>Fornecedor: <?= e($record['fornecedor'] ?? 'Não informado') ?></p><p>Valor contratado: <?= e(Contrato::money($record['valor_centavos']===null ? null : (int)$record['valor_centavos'])) ?></p>
<?php foreach ($sheets as $sheet): if ($sheetId!==null && (int)$sheet['id']!==$sheetId) { continue; } ?><section><h2>Folha <?= (int)$sheet['numero_pagina'] ?></h2><p><?= nl2br(e($sheet['observacao'] ?? '')) ?></p><table><thead><tr><th>Produto</th><th>Unidade</th><th>Quantidade contratada</th><th>Preço</th><th>Total</th></tr></thead><tbody><?php foreach ($items as $item): if ((int)$item['numero_pagina']!==(int)$sheet['numero_pagina'] || $item['excluido_em']!==null) { continue; } ?><tr><td><?= e($item['nome_produto']) ?></td><td><?= e($item['unidade']) ?></td><td><?= e($item['quantidade_contratada'] ?? $item['quantidade']) ?></td><td><?= e(Contrato::money($item['preco_centavos']===null ? null : (int)$item['preco_centavos'])) ?></td><td><?= e(Contrato::money($item['total_centavos']===null ? null : (int)$item['total_centavos'])) ?></td></tr><?php endforeach; ?></tbody></table><p>Total da folha: <?= e(Contrato::money($sheet['valor_centavos']===null ? null : (int)$sheet['valor_centavos'])) ?></p><p>Faturamento documental: <?= e($sheet['data_faturamento'] ?? 'não registrado') ?></p></section><?php endforeach; ?>
</body></html>
